curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/x-www-form-urlencoded" -d "token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"{ch['id']} | created={ch['created']} | name={ch['name']} | is_private={ch['is_private']}\")
else:
    print(data)
"
